#!/usr/bin/env python3
"""Prepare and verify Icon256 release assets without modifying upstream build code."""
# AI: below section was generated by an AI
import argparse
import hashlib
import json
import re
import shutil
import struct
from datetime import datetime, timezone
from pathlib import Path

RELEASE_NAME = 'ESP32_S3_Icon256'
MAX_APP_SIZE = 0x180000  # Both OTA slots in WLED_ESP32_4MB_1MB_FS.csv
META = struct.Struct('<II48s48sI3B')
SEMVER = re.compile(r'^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)'
                    r'(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?'
                    r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$')


def version_from_tag(tag):
    version = tag[1:] if tag.startswith('v') else ''
    match = SEMVER.fullmatch(version)
    if not match or len(version.encode()) >= 48:
        raise ValueError('Use a v-prefixed semantic version shorter than 48 bytes')
    prerelease = match.group(4)
    if prerelease and any(p.isdigit() and len(p) > 1 and p[0] == '0' for p in prerelease.split('.')):
        raise ValueError('Numeric prerelease identifiers cannot have leading zeros')
    return version, bool(prerelease)


def validate_repository(repository):
    if not re.fullmatch(r'[A-Za-z0-9_-]+/[A-Za-z0-9_.-]+', repository):
        raise ValueError('Expected GitHub owner/repository')


def prepare(root, tag):
    """Set package and lock versions in the disposable release checkout, before npm ci."""
    version, prerelease = version_from_tag(tag)
    for filename in ('package.json', 'package-lock.json'):
        path = root / filename
        document = json.loads(path.read_text())
        document['version'] = version
        if filename == 'package-lock.json' and '' in document.get('packages', {}):
            document['packages']['']['version'] = version
        path.write_text(json.dumps(document, indent=2) + '\n')
    return version, prerelease


def inspect_firmware(data, version):
    """Reject wrong boards, truncated/corrupt images, and mismatched WLED metadata."""
    if not 24 < len(data) <= MAX_APP_SIZE or data[0] != 0xE9:
        raise ValueError('Not an ESP application image fitting the Icon256 OTA slot')
    if struct.unpack_from('<H', data, 12)[0] != 9:
        raise ValueError('Firmware is not for ESP32-S3')
    if data[3] >> 4 != 2:  # ESP image flash-size code 2 = 4 MB
        raise ValueError('Firmware does not declare 4 MB flash')
    if not 1 <= data[1] <= 16 or data[23] != 1:
        raise ValueError('Expected a hashed ESP application image')
    offset, checksum = 24, 0xEF
    segments = []
    for _ in range(data[1]):
        if offset + 8 > len(data):
            raise ValueError('Truncated segment header')
        _, size = struct.unpack_from('<II', data, offset)
        offset += 8
        if offset + size > len(data):
            raise ValueError('Truncated segment')
        segment = data[offset:offset+size]
        segments.append(segment)
        for byte in segment:
            checksum ^= byte
        offset += size
    checksum_offset = (offset // 16 + 1) * 16 - 1
    digest_offset = checksum_offset + 1
    if len(data) != digest_offset + 32:
        raise ValueError('Unexpected image length (unsigned OTA image required)')
    if data[checksum_offset] != checksum:
        raise ValueError('ESP checksum mismatch')
    if hashlib.sha256(data[:digest_offset]).digest() != data[digest_offset:]:
        raise ValueError('ESP image SHA-256 mismatch')
    matches = []
    magic = struct.pack('<I', 0x57535453)
    for segment in segments:
        start = 0
        while (position := segment.find(magic, start)) != -1:
            start = position + 1
            if position + META.size > len(segment):
                continue
            _, revision, raw_version, raw_name, name_hash, *safe = META.unpack_from(segment, position)
            try:
                embedded_version = raw_version.split(b'\0', 1)[0].decode('ascii')
                name = raw_name.split(b'\0', 1)[0].decode('ascii')
            except UnicodeDecodeError:
                continue
            expected_hash = 5381
            for byte in name.encode():
                expected_hash = (expected_hash * 33 + byte) & 0xFFFFFFFF
            if revision in (1, 2) and expected_hash == name_hash:
                matches.append((embedded_version, name))
    if matches != [(version, RELEASE_NAME)]:
        raise ValueError(f'Embedded metadata must be exactly {version} / {RELEASE_NAME}; found {matches}')


def package(firmware, out, tag, repository, commit):
    version, prerelease = version_from_tag(tag)
    validate_repository(repository)
    if not re.fullmatch(r'[0-9a-f]{40}', commit):
        raise ValueError('Source commit must be a full Git SHA')
    data = firmware.read_bytes()
    inspect_firmware(data, version)
    filename = f'WLED_{version}_{RELEASE_NAME}.bin'
    base = f'https://github.com/{repository}/releases'
    manifest = {
        'schema_version': 1, 'version': version, 'tag': tag, 'repository': repository,
        'channel': 'prerelease' if prerelease else 'stable', 'source_commit': commit,
        'built_at': datetime.now(timezone.utc).isoformat(),
        'release_notes': f'{base}/tag/{tag}',
        'firmware': {
            'target': 'icon256', 'chip': 'esp32s3', 'flash_size': 4194304,
            'release_name': RELEASE_NAME, 'format': 'esp-app', 'offset': 65536,
            'max_size': MAX_APP_SIZE, 'size': len(data),
            'sha256': hashlib.sha256(data).hexdigest(),
            'filename': filename, 'url': f'{base}/download/{tag}/{filename}',
        },
    }
    out.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(firmware, out / filename)
    (out / 'manifest.json').write_text(json.dumps(manifest, indent=2) + '\n')
    (out / 'SHA256SUMS').write_text(f'{manifest["firmware"]["sha256"]}  {filename}\n')
    (out / 'release-notes.md').write_text(
        f'Icon256 {version}\n\n'
        'Draft for validation. Includes the simplified control UI, word clock, text, '
        'audio-reactive equalizer and digital rain.\n\n'
        f'Source commit: `{commit}`. Hardware: `{RELEASE_NAME}`, ESP32-S3, 4 MB flash.\n\n'
        f'Use `{filename}` with WLED firmware update (OTA). This is an application '
        'image, not a full-flash factory image. Back up configuration and presets before testing.\n\n'
        'The attached manifest provides compatibility, size and SHA-256 information. '
        'The simplified UI discovers published releases through the verified update feed; prereleases require the testing option.\n\n'
        'Publishing this draft makes its assets public; review and test before publishing.\n'
    )
    verify(out / 'manifest.json')
    return manifest


def verify(path):
    manifest = json.loads(path.read_text())
    if manifest['schema_version'] != 1:
        raise ValueError('Unsupported manifest schema')
    version, prerelease = version_from_tag(manifest['tag'])
    validate_repository(manifest['repository'])
    if not re.fullmatch(r'[0-9a-f]{40}', manifest['source_commit']):
        raise ValueError('Invalid source commit')
    if manifest['release_notes'] != f'https://github.com/{manifest["repository"]}/releases/tag/{manifest["tag"]}':
        raise ValueError('Unexpected release-notes URL')
    firmware = manifest['firmware']
    expected = f'WLED_{version}_{RELEASE_NAME}.bin'
    if firmware['filename'] != expected or manifest['version'] != version:
        raise ValueError('Manifest version/filename mismatch')
    if manifest['channel'] != ('prerelease' if prerelease else 'stable'):
        raise ValueError('Manifest channel mismatch')
    for key, value in {'target':'icon256', 'chip':'esp32s3', 'flash_size':4194304,
                       'release_name':RELEASE_NAME, 'format':'esp-app', 'offset':65536,
                       'max_size':MAX_APP_SIZE}.items():
        if firmware[key] != value:
            raise ValueError(f'Manifest compatibility mismatch: {key}')
    if firmware['url'] != f'https://github.com/{manifest["repository"]}/releases/download/{manifest["tag"]}/{expected}':
        raise ValueError('Unexpected firmware URL')
    data = (path.parent / expected).read_bytes()
    inspect_firmware(data, version)
    if firmware['size'] != len(data) or firmware['sha256'] != hashlib.sha256(data).hexdigest():
        raise ValueError('Manifest size or SHA-256 mismatch')
    checksums = path.parent / 'SHA256SUMS'
    if checksums.read_text() != f'{firmware["sha256"]}  {expected}\n':
        raise ValueError('SHA256SUMS mismatch')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest='command', required=True)
    prep = commands.add_parser('prepare')
    prep.add_argument('--tag', required=True)
    prep.add_argument('--root', type=Path, default=Path('.'))
    prep.add_argument('--github-output', type=Path)
    pack = commands.add_parser('package')
    for name in ('tag', 'repository', 'commit'):
        pack.add_argument('--'+name, required=True)
    pack.add_argument('--firmware', type=Path, required=True)
    pack.add_argument('--out', type=Path, required=True)
    check = commands.add_parser('verify')
    check.add_argument('manifest', type=Path)
    args = parser.parse_args()
    if args.command == 'prepare':
        version, prerelease = prepare(args.root, args.tag)
        if args.github_output:
            with args.github_output.open('a') as output:
                output.write(f'version={version}\nprerelease={str(prerelease).lower()}\n')
        print(f'Prepared {version}; prerelease={prerelease}')
    elif args.command == 'package':
        print(json.dumps(package(args.firmware, args.out, args.tag, args.repository, args.commit), indent=2))
    else:
        verify(args.manifest)
        print('Release package verified')


if __name__ == '__main__':
    main()
